 box(.12,2.6,.6,silver,-3,0,-.1);for(let i=0;i<3;i++)box(.13,.3,.16,black,-3.07,-.55+i*.5,-.05);box(.65,.16,.3,black,1.9,1.14,-.12,pcb);
